'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,n=2)=>Number(v).toFixed(n).replace(/\.?0+$/,'');
const C=['#cc715e','#6d88c1','#65986d','#ba91b5'];
const STAGES=['情境导入','项目探究','项目实施','成果与自测'];
const TITLES=['先猜一猜，你是哪种作息星人？','把相似的作息，一步步聚在一起','换一个 k，发现另一种分法','给数据起名，也给结论留一点空间'];
const SUBS=['留下一份直觉，课末再用数据验证。','只做两件事：算距离，求均值。','同一批教学样本，分几类由你来决定。','先解释群体特点，再看看自己的数据落在哪里。'];
const QUESTIONS=['我为什么要标准化？','中心点怎样更新？','k 应该怎么选？'];
const RATINGS=['能说出 K-means 的循环过程','能用距离平方判断归属','能分别求均值，算出新中心','能解释为什么先统一尺度','知道 k 和名字由人决定，分组不能定义人'];
let S=null,studentId=null,room={},votePick=null,feedback='',chatBusy=false,teacherData=null,roomCode='',projector=false,postData=null,postResult=null,toastTimer,saveTimer,animateCenters=false;
let reasonRequest=null;
const params=new URLSearchParams(location.search),teacherView=params.get('view')==='teacher',afterView=params.get('view')==='after';
function toast(t){$('#toast').textContent=t;$('#toast').className='show';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').className='',4500);}
function persist(){if(!S)return;S.updatedAt=new Date().toISOString();Store.save(studentId,S).catch(()=>toast('已保存到本机；云端暂未同步，恢复连接后会重试。'));}
function modeLabel(){return Store.mode==='cloud'?(Store.online?(S?'课堂已连接':teacherView?'正式课堂 · 教师端':'正式课堂入口'):'待重新同步'):'本机体验 · 无需课堂码';}
function entryHref(){return /\/offline\.html$/i.test(location.pathname)?'offline.html':params.get('mode')==='experience'?'index.html?mode=experience':'index.html';}
function viewHref(view,code){const q=new URLSearchParams({view});if(params.get('mode')==='experience')q.set('mode','experience');if(code)q.set('class',code);return '?'+q.toString();}
function header(){return `<header class="topbar"><a class="brand" href="${entryHref()}"><span class="brand-mark">✦</span><span>作息星球 <small> / K-MEANS LAB</small></span></a><div class="top-meta"><span class="tag neutral" id="modeLabel">${modeLabel()}</span>${S?`<span class="identity">${esc(S.className)} · ${esc(S.name)}</span><button class="ghost" data-action="logout">退出</button>`:`<a href="${viewHref('teacher')}">教师工作台 ↗</a>`}</div></header>`;}
function heroArt(){return `<svg viewBox="0 0 520 580" aria-label="三组作息星人围绕各自中心聚集的插画" role="img"><defs><pattern id="grid" width="29" height="29" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#bacab4" opacity=".55"/></pattern></defs><rect width="520" height="580" fill="url(#grid)"/><circle cx="264" cy="264" r="177" fill="none" stroke="#c1d1b7"/><circle cx="264" cy="264" r="123" fill="none" stroke="#c7d6bf" stroke-dasharray="4 7"/><path d="M75 400 L440 400 M110 450 L110 100" stroke="#a6b99d" fill="none"/><text x="380" y="425" fill="#7a9070" font-size="12">睡眠 →</text><text x="70" y="100" fill="#7a9070" font-size="12">运动 ↑</text><g transform="translate(345 182) rotate(-10)"><ellipse rx="81" ry="71" fill="#cadcaf"/><circle cx="-23" cy="-12" r="5" fill="#45644b"/><circle cx="23" cy="-12" r="5" fill="#45644b"/><path d="M-15 13 Q0 33 15 13" stroke="#45644b" fill="none" stroke-width="4" stroke-linecap="round"/><path d="M-53 -65 L-64 -87 M-27 -76 L-27 -100 M2 -76 L10 -94" stroke="#93b075" stroke-width="4" stroke-linecap="round"/><text x="0" y="99" text-anchor="middle" fill="#66805b" font-size="12">睡够 + 爱动</text></g><g transform="translate(340 360) rotate(9)"><ellipse rx="70" ry="63" fill="#d0dbe9"/><circle cx="-21" cy="-8" r="4.5" fill="#657e9d"/><circle cx="21" cy="-8" r="4.5" fill="#657e9d"/><path d="M-10 16 Q0 24 10 16" stroke="#657e9d" stroke-width="3" fill="none" stroke-linecap="round"/><text x="0" y="89" text-anchor="middle" fill="#71869d" font-size="12">睡够 + 宅</text></g><g transform="translate(161 350) rotate(-8)"><ellipse rx="58" ry="53" fill="#e8cfae"/><path d="M-28 -8 l15 0 M14 -8 l15 0 M-6 16 l12 0" stroke="#a2815c" stroke-width="3.5" stroke-linecap="round"/><text x="32" y="-48" fill="#a98d6a" font-size="19" font-family="monospace">z</text><text x="49" y="-65" fill="#a98d6a" font-size="15" font-family="monospace">z</text><text x="0" y="82" text-anchor="middle" fill="#9b805e" font-size="12">熬夜 + 不动</text></g>${[[255,132],[430,234],[370,90],[395,285],[244,402],[420,388],[208,292],[133,426],[98,298]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="${i%3+4}" fill="${['#8aa275','#90a4bf','#c7a781'][Math.floor(i/3)]}"/>`).join('')}<text x="45" y="48" fill="#71866b" font-family="monospace" font-size="10" letter-spacing="3">FIND YOUR CONSTELLATION</text><text x="438" y="488" fill="#8ca180" font-size="25">✧</text></svg>`;}
function renderLanding(){
 const code=params.get('class')||'',cloud=Store.mode==='cloud';
 $('#app').innerHTML=header()+`<main class="landing"><section class="hero"><div class="hero-copy"><div class="eyebrow">高中人工智能 · 一次关于相似性的探索</div><h1>你是哪种<br>作息星人<span style="color:#8eab76">？</span></h1><p class="muted">每天睡多久，运动多久？<br>让两个普通的数，带你走进 K-means 聚类。</p><div class="hero-facts"><div><b>02</b><span>个作息特征</span></div><div><b>40</b><span>个教学样本</span></div><div><b>∞</b><span>种认识自己的可能</span></div></div>
 ${cloud?'<div class="entry-choice"><span>想先试用完整课堂？</span><button type="button" data-action="tryLocal">无需课堂码，先体验 →</button></div>':'<div class="entry-choice"><span>本机体验</span><strong>只需姓名和班级，即可开始</strong></div>'}
 <form id="joinForm"><div class="join-grid"><div class="field"><label for="studentName">你的姓名</label><input id="studentName" name="name" maxlength="24" placeholder="怎么称呼你" autocomplete="name" required></div><div class="field"><label for="className">所在班级</label><input id="className" name="className" maxlength="40" value="${esc(params.get('className')||'')}" placeholder="例如：高一（3）班" required></div>${cloud?`<div class="field full"><label for="classCode">课堂码</label><input id="classCode" name="code" value="${esc(code)}" placeholder="填写教师创建课堂后提供的课堂码" maxlength="20" aria-describedby="classCodeHelp" required><p class="small muted" id="classCodeHelp" style="margin:7px 0 0">正式课堂需先由教师创建；自行填写的 test01 等名称不会自动创建课堂。</p></div>`:''}<div id="joinError" class="full error" role="alert" hidden></div><button class="primary full" type="submit">进入作息实验室 <span aria-hidden="true">→</span></button></div></form><p class="small muted" style="font-size:10px;margin:13px 0 0">${cloud?'姓名与学习过程用于本课堂教学反馈。':'本机体验：记录只保存在此浏览器，支持离线学习。'}</p>${!cloud&&location.protocol!=='file:'?'<a class="small" href="index.html" style="display:inline-block;margin-top:12px">已有老师的课堂码？加入正式课堂 ↗</a>':''}</div><div class="hero-art">${heroArt()}<div class="art-caption">机器寻找数据中的相似性，你赋予它们意义。</div></div></section><div class="landing-foot"><span>先猜测 · 再探究 · 做实验 · 看见自己</span><span>机器分的是作息，不是定义你这个人。</span></div></main>`;
}
function tutorHtml(){const messages=(S.messages||[]).slice(-16);return `<aside class="tutor" aria-label="学习助教"><div class="tutor-head"><div class="avatar">✧</div><div><h3>星伴 · 学习搭子</h3><span class="small muted" style="font-size:10px">陪你想一想，再向前一步</span></div></div><div class="tutor-body" id="chatMessages" aria-live="polite">${messages.length?messages.map(m=>`<div class="message-source">${m.role==='user'?'你':esc(m.source||'本地导学')}</div><div class="bubble ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join(''):`<div class="bubble">${Tutor.fallback('welcome',S)}</div>`}${chatBusy?'<div class="small muted">星伴正在思考…</div>':''}</div><div class="tutor-bottom"><div class="quick">${QUESTIONS.map(q=>`<button data-action="quick" data-question="${q}">${q}</button>`).join('')}</div><form id="chatForm"><label class="sr-only" for="chatInput">向学习搭子提问</label><textarea id="chatInput" maxlength="500" placeholder="告诉我，你卡在哪一步？" required></textarea><button class="ghost wide small" ${chatBusy?'disabled':''}>发送问题 ↗</button></form></div><div class="tutor-note">${Store.mode==='local'?'当前为本地导学，使用预置提示。':'在线 AI 不可用时，自动使用本地导学。'}</div></aside>`;}
function allowed(){let a=0;while(a<3&&S.completed[a])a++;return Math.max(a,room.unlocked||0);}
function render(){if(S)KM.upgradeState(S);if(teacherView)return renderTeacher();if(afterView)return renderAfter();if(!S)return renderLanding();if(S.stage>allowed())S.stage=allowed();$('#app').innerHTML=header()+`<nav class="progress-nav" aria-label="课堂环节">${STAGES.map((t,i)=>`<button class="step ${S.stage===i?'active':''}" data-action="stage" data-stage="${i}" ${i>allowed()?'disabled':''}><span class="step-number">${S.completed[i]?'✓':String(i+1).padStart(2,'0')}</span><span>${t}<small>${S.completed[i]?'已完成':i>allowed()?'完成前一环节后开启':i===S.stage?'正在探索':'等待探索'}</small></span></button>`).join('')}</nav><div class="workspace"><main class="main">${room.frozen?`<div class="notice">本课堂成果已定格。可以继续回看，或进入 <a href="${viewHref('after',room.code||S.className)}">课后作息图鉴 →</a></div>`:''}<div class="section-head"><div class="eyebrow">CHAPTER ${String(S.stage+1).padStart(2,'0')} / ${STAGES[S.stage]}</div><h2>${TITLES[S.stage]}</h2><p>${SUBS[S.stage]}</p></div>${[viewVote,viewExplore,viewLab,viewFinish][S.stage]()}<div class="section-foot"><span class="small muted">${S.completed.filter(Boolean).length} / 4 个环节已完成 · ${Store.mode==='local'?'本机自动保存':'自动保存课堂记录'}</span><div class="row">${S.stage>0?`<button data-action="stage" data-stage="${S.stage-1}">← 上一环节</button>`:''}${S.completed[S.stage]&&S.stage<3?`<button class="primary" data-action="stage" data-stage="${S.stage+1}">继续下一环节 →</button>`:''}</div></div></main>${tutorHtml()}</div>`;bindPlot();}
function viewVote(){return `<section class="card"><div class="row between" style="margin-bottom:20px"><h3 style="margin:0">如果凭直觉，你会选哪一个？</h3><span class="tag neutral">没有标准答案</span></div><div class="grid3">${KM.TYPES.map((t,i)=>`<button class="vote-card ${(votePick??S.vote)===i?'selected':''}" data-action="votePick" data-value="${i}" aria-pressed="${(votePick??S.vote)===i}"><span class="select-dot"></span><div class="character ${['','blue','orange'][i]}"></div><h3>${t}</h3><p>${['睡够 + 爱动','睡够 + 宅','熬夜 + 不动'][i]}</p><span class="card-number">0${i+1}</span></button>`).join('')}</div><div class="row between" style="margin-top:23px"><span class="small muted">最后再看：机器分的，和你猜的一样吗？</span><button class="primary" data-action="vote" ${votePick===null&&S.vote===null?'disabled':''}>${S.vote!==null?'更新我的猜测':'留下我的猜测'} →</button></div></section>${S.completed[0]?`<section class="card grid2"><div><div class="quote-mark">“</div><p class="quote">机器没有直觉，也不贴标签。<br>它只盯着两个数，算谁跟谁像。<br><strong>这叫聚类。</strong></p></div><div><h3>课堂的第一份直觉</h3><div id="voteBars"><p class="muted small">正在汇总…</p></div><p class="small muted" style="margin-top:15px">${Store.mode==='local'?'仅统计此浏览器的体验记录。':'按当前课堂汇总，不展示他人姓名。'}</p></div></section>`:''}`;}
function plot(points,centers=[],labels=[],{hand=false,selected=-1,distances=false,previous=[],self=-1,interactive=false}={}){const all=[...points,...centers],minX=Math.min(0,...all.map(p=>p[0])),maxX=Math.max(10,...all.map(p=>p[0])),minY=Math.min(0,...all.map(p=>p[1])),maxY=Math.max(10,...all.map(p=>p[1]));const low=Math.floor(Math.min(minX,minY)),high=Math.ceil(Math.max(maxX,maxY)),scale=340/(high-low||10),px=p=>[62+(p[0]-low)*scale,378-(p[1]-low)*scale];const ticks=Array.from({length:6},(_,i)=>low+(high-low)*i/5);return `<svg class="plot" id="plot" viewBox="0 0 470 435" role="img" aria-label="睡眠与运动散点图，圆点为样本，菱形为中心" data-low="${low}" data-high="${high}">${ticks.map(v=>{const [x,y]=px([v,v]);return `<line x1="${x}" y1="38" x2="${x}" y2="378" stroke="#e3eadd"/><line x1="62" y1="${y}" x2="402" y2="${y}" stroke="#e3eadd"/><text x="${x}" y="400" text-anchor="middle" class="plot-label">${fmt(v,1)||'0'}</text><text x="45" y="${y+4}" text-anchor="end" class="plot-label">${fmt(v,1)||'0'}</text>`;}).join('')}<path d="M62 30 V378 H417" stroke="#a9bba2" fill="none"/><text x="66" y="20" class="plot-label">运动（分）</text><text x="323" y="426" class="plot-label">睡眠（分）</text>${previous.map((c,i)=>{const [x,y]=px(c),[nx,ny]=px(centers[i]);return `<path d="M${x} ${y} L${nx} ${ny}" stroke="${C[i]}" stroke-dasharray="4 3"/><path d="M${x} ${y-8} l8 8 l-8 8 l-8 -8Z" fill="none" stroke="${C[i]}" opacity=".55"/>`;}).join('')}${distances&&selected>=0?centers.map((c,i)=>{const [x,y]=px(points[selected]),[cx,cy]=px(c);return `<line x1="${x}" y1="${y}" x2="${cx}" y2="${cy}" stroke="${C[i]}" stroke-dasharray="5 4" stroke-width="1.5"/><text x="${(x+cx)/2+5}" y="${(y+cy)/2-6}" font-size="11" fill="${C[i]}">d²=${fmt(KM.distance2(points[selected],c))||'0'}</text>`;}).join(''):''}${points.map((p,i)=>{const [x,y]=px(p),color=labels[i]>=0?C[labels[i]]:'#a9b5a2';return `<g ${hand?`data-point="${i}" tabindex="0" role="button" aria-label="选择 P${i+1}，坐标 ${p[0]}, ${p[1]}"`:''}><circle class="point" cx="${x}" cy="${y}" r="${i===self?9:hand?7:5}" fill="${color}" stroke="${i===selected||i===self?'#234c40':'white'}" stroke-width="${i===selected||i===self?3:1.7}"><title>${i===self?'我':(hand?'P':'S')+(i+1)} (${p.map(v=>fmt(v)).join(', ')})</title></circle>${hand||i===self?`<text x="${x+10}" y="${y-10}" font-size="11" fill="#4e6655">${i===self?'我':'P'+(i+1)}</text>`:''}</g>`;}).join('')}${centers.map((p,i)=>{const [x,y]=px(p);return `<g class="center ${interactive?'draggable':''}" data-center="${i}" transform="translate(${x} ${y})"><path d="M0 -10 L10 0 L0 10 L-10 0Z" fill="${C[i]}" stroke="white" stroke-width="2"/><text x="12" y="5" fill="${C[i]}" font-size="12" font-weight="bold">${String.fromCharCode(65+i)}</text><title>中心 ${String.fromCharCode(65+i)} (${p.map(v=>fmt(v)).join(', ')})</title></g>`;}).join('')}</svg>`;}
function legend(k=3){return `<div class="legend"><span>● 样本</span>${Array.from({length:k},(_,i)=>`<span><i class="dot" style="background:${C[i]}"></i>簇 ${String.fromCharCode(65+i)} · ◆ 中心</span>`).join('')}</div>`;}
function exploreStep(){return S.exploreView??S.step;}
function viewExplore(){if(!S.normalized||exploreStep()===-1)return `<section class="card"><div class="row between"><h3>先给两个特征一把共同的尺子</h3><span class="tag">任务 01 · 标准化</span></div><p class="muted small">睡眠以小时计，运动以分钟计。直接算距离，数值更大的运动项可能占主导。</p><div class="grid2"><div class="soft"><span class="small muted">同一个样本 P1</span><div class="scale-box"><div><span class="small">睡眠</span><div class="scale-value">8.4 <small>h</small></div></div><span class="scale-arrow">＋</span><div><span class="small">运动</span><div class="scale-value">54 <small>min</small></div></div></div></div><div class="soft"><span class="small muted">共同参考尺度</span><h2 style="margin:14px 0 8px">0 — 10 分</h2><p class="small muted">睡眠 6–9 h → 0–10 分<br>运动 0–90 min → 0–10 分</p></div></div><div class="row between" style="margin-top:24px"><span class="small muted">分数表达数据位置，不代表作息优劣。</span><button class="primary" data-action="normalize">${S.normalized?'返回手算步骤 →':'一键标准化 →'}</button></div></section>`;
  const steps=['定 k','初始化','分配','更新','重复','收敛'],step=exploreStep(),v=KM.handView(S,step);return `<section class="card"><div class="row between"><div><span class="tag">已统一尺度</span><span class="small muted" style="margin-left:10px">P1：8.4 h / 54 min → <strong class="mapped">(8, 6)</strong></span></div><span class="small muted">第 ${step+1} 步 / 6 步</span></div><nav class="wizard" aria-label="手算步骤">${steps.map((t,i)=>`<button data-action="exploreView" data-step="${i}" class="${i===step?'current':i<S.step?'done':''}" ${i>S.step?'disabled':''} ${i===step?'aria-current="step"':''}>${i<S.step?'✓':i+1} ${t}</button>`).join('')}</nav>${step<S.step?'<div class="notice review-note">正在回看，已做的答案会保留。<button class="ghost small" data-action="resumeExplore">返回当前进度 →</button></div>':''}<div class="lab-layout"><div><div class="plot-wrap">${plot(KM.HAND,v.centers,v.labels,{hand:true,selected:S.selected,distances:step===2&&S.evidence.distance.passed,previous:v.previous})}${legend()}</div><p class="small muted" style="margin:9px 0">8 个手算样本 · 横轴为睡眠，纵轴为运动 · 两轴等比例</p>${step===2?`<div class="point-list">${KM.HAND.map((p,i)=>`<button data-action="point" data-index="${i}" class="${S.selected===i?'active':''} ${v.labels[i]>=0?'assigned':''}">P${i+1}${v.labels[i]>=0?' ✓':''}</button>`).join('')}</div>`:''}</div><div class="task">${exploreTask()}${feedback?`<div class="feedback" role="status">${esc(feedback)}</div>`:''}</div></div>${step>=4?`<details style="margin-top:20px"><summary>查看本轮分组与均值</summary>${centerTable(KM.HAND,v)}</details>`:''}<div class="row between hand-navigation"><button data-action="exploreBack">← ${step===0?'回看标准化':'上一步'}</button><span class="small muted">可点击上方已到达的步骤回看</span></div>${S.handHistory.length?`<details class="hand-history"><summary>此前的手算记录（${S.handHistory.length} 轮）</summary>${S.handHistory.map(handHistoryHtml).join('')}</details>`:''}</section>`;}
function handHistoryHtml(h){return `<div class="soft" style="margin-top:10px"><strong>第 ${h.round+1} 轮 · ${h.completed?'已完成探究':'练习记录'}</strong><p class="small">初始中心：${h.initialCenters.map((p,i)=>String.fromCharCode(65+i)+' ('+p.map(v=>fmt(v)).join(', ')+')').join('；')}</p>${['distance','mean'].map(k=>`<p class="small">${k==='distance'?'距离':'均值'}：${KM.grade(h.evidence[k])} · 提示 ${h.evidence[k].hints} 次<br>${h.evidence[k].attempts.map(a=>`${k==='distance'?esc(a.answer.value)+' / '+String.fromCharCode(65+Number(a.answer.cluster)):'('+esc(a.answer.x)+', '+esc(a.answer.y)+')'}（${a.passed?'正确':'需订正'}）`).join('；')||'暂无作答'}</p>`).join('')}</div>`;}

function exploreTask(){const step=exploreStep(),v=KM.handView(S,step);if(step<S.step&&step>=2)return `<span class="tag">回看第 ${step+1} 步</span><h3>${['','','按初始中心判断归属','第一轮均值更新','重复分配与更新'][step]}</h3><p>${step===2?'这里显示当时的初始中心和第一轮分配，点击样本可查看距离。':step===3?'这里显示第一轮更新后的中心，虚线连接更新前后的位置。均值可能是小数，不一定落在样本点上。':'这里保留本轮重复计算后的结果。'}</p>${step<=3?`<span class="tag">${KM.grade(S.evidence[step===2?'distance':'mean'])}</span>`:''}${centerTable(KM.HAND,v)}<button class="primary" data-action="exploreNext">继续回看下一步 →</button>`;switch(step){case 0:return `<span class="eyebrow">STEP 01</span><h3>我们先试着分成三类</h3><p>k 表示你想分成的簇数。先用 k=3，后面再试其他选择。</p><div class="soft"><span class="small muted">本轮手算</span><div style="font-size:36px;color:var(--green)">k = 3</div></div><button class="primary" data-action="exploreNext">确认 k=3 →</button>`;
case 1:{const centers=v.centers,changed=JSON.stringify(centers)!==JSON.stringify(S.initialCenters);return `<span class="eyebrow">STEP 02</span><h3>从样本中选三个初始中心</h3><p>本课从 P1–P8 中选三个不同的整数样本。菱形标出被选为中心的样本，第一轮距离更方便手算。</p><div id="centerInputs">${centers.map((p,i)=>`<label>中心 ${String.fromCharCode(65+i)}<select aria-label="中心 ${String.fromCharCode(65+i)} 的样本" data-center-sample="${i}">${KM.HAND.map((point,j)=>`<option value="${j}" ${KM.distance2(p,point)===0?'selected':''} ${centers.some((q,n)=>n!==i&&KM.distance2(q,point)===0)?'disabled':''}>P${j+1} · (${point.join(', ')})</option>`).join('')}</select></label>`).join('')}</div><p class="small muted">默认：A=P2，B=P5，C=P7。更新后的中心是均值，可能为小数，也可能不在样本点上。</p>${S.initialCenters&&changed?'<div class="notice">更换起点将开启新一轮距离与均值练习，此前的作答会保留在历史记录中。</div>':''}<button class="ghost small" data-action="resetCenters">恢复课堂起点</button><button class="primary" data-action="exploreNext">${S.step>=2?(changed?'用这些样本开始新一轮 →':'回到本轮分配 →'):'从这里开始分配 →'}</button>`;}

case 2:if(!S.evidence.distance.passed)return `<span class="eyebrow">STEP 03 · 先独立判断</span><h3>P1 应该归哪一簇？</h3><p>P1=(8,6)。请计算它到 A 的距离平方，再比较三个中心，选择最近的一簇。</p><div class="formula">d² = (x − a)² + (y − b)²<br>${v.centers.map((c,i)=>`${String.fromCharCode(65+i)} (${c.map(v=>fmt(v)).join(', ')})`).join('<br>')}</div><form id="distanceForm" class="stack" style="gap:10px"><label>到 A 的距离平方<input name="distance" type="number" min="0" step="any" placeholder="输入你算出的数" value="${esc(S.handDrafts?.distance??'')}" required></label><label>最近的中心<select name="cluster" required><option value="">请先比较，再选择</option>${v.centers.map((_,i)=>`<option value="${i}" ${String(S.handDrafts?.cluster)===String(i)?'selected':''}>${String.fromCharCode(65+i)} 中心</option>`).join('')}</select></label><button class="primary">检验我的判断</button></form>${hintHtml('distance')}`;return `<span class="tag">${KM.grade(S.evidence.distance)}</span><h3>现在让每个点归最近</h3><p>选中 P${S.selected+1}，看三条虚线上的距离平方。最小的值对应哪一簇？</p><button class="primary" data-action="assignOne">P${S.selected+1} 归最近 →</button><button data-action="assignAll">其余点自动分配</button><span class="small muted">已分配 ${S.labels.filter(x=>x>=0).length} / 8 个点</span><button class="primary" data-action="exploreNext" ${S.labels.some(x=>x<0)?'disabled':''}>分配完成，计算均值 →</button>`;
case 3:if(!S.evidence.mean.passed){const members=KM.HAND.filter((_,i)=>S.labels[i]===1);return `<span class="eyebrow">STEP 04 · 先独立计算</span><h3>算一算 B 簇的新中心</h3><p>这一簇的点是：${members.map(p=>'('+p.join(', ')+')').join('、')}。横、纵坐标分别求平均。</p><form id="meanForm" class="stack" style="gap:10px"><label>新中心横坐标<input name="x" type="number" step="any" required placeholder="横坐标的平均值" value="${esc(S.handDrafts?.x??'')}"></label><label>新中心纵坐标<input name="y" type="number" step="any" required placeholder="可保留一位小数" value="${esc(S.handDrafts?.y??'')}"></label><button class="primary">检验我的均值</button></form>${hintHtml('mean')}`;}return `<span class="tag">${KM.grade(S.evidence.mean)}</span><h3>${S.updated?'中心已经移到均值位置':'让中心移动到均值位置'}</h3><p>${S.updated?S.centers.map((p,i)=>`${String.fromCharCode(65+i)}′ (${p.map(v=>fmt(v,1)).join(', ')})`).join('<br>'):'你已算出 B 的新中心，其余中心由工具一起更新。均值可能是小数，后续迭代由工具计算。'}</p>${!S.updated?'<button class="primary" data-action="updateCenters">重算均值 →</button>':'<button class="primary" data-action="exploreNext">继续下一轮 →</button>'}`;
case 4:return `<span class="eyebrow">STEP 05</span><h3>再分配，再更新</h3><p>中心变了，每个点都要重新比较距离。重复这两步，观察中心还会不会移动。</p><div class="soft"><span class="small muted">已经重复</span><h2 style="margin:6px 0">${S.repeatCount} 轮</h2><span class="small muted">${S.repeatCount?S.converged?'中心不再移动':'中心还在移动':'等待你的下一轮操作'}</span></div><button class="primary" data-action="repeat">再分配 → 再更新</button><button data-action="exploreNext" ${!S.converged?'disabled':''}>中心不动了，去总结 →</button>`;
case 5:return `<span class="eyebrow">STEP 06 · 收敛</span><h3>为什么现在可以停下来？</h3><p>分配与更新后，中心点不再移动。这就是本课的停止条件。</p><div class="soft"><strong>定 k → 初始化</strong><div style="margin:9px 0">↓</div><strong>分配 → 更新 → 再分配</strong><div style="margin:9px 0">↓</div><strong>直到中心点不再移动</strong></div><button class="primary" data-action="completeExplore">完成探究 ✓</button>`;}}
function hintHtml(type){const e=S.evidence[type],hints=type==='distance'?['先算 P1 与 A 在睡眠这一轴上的差，再算运动这一轴上的差。','分别平方后相加；判断归属时，要把 P1 到 A、B、C 的平方和都比较一次。']:['把同一簇所有点的横坐标相加，再除以点数。纵坐标单独计算。','不要把横纵坐标混在一起平均。两个分母都应等于这一簇的成员数。'];return `<button class="ghost small" data-action="hint" data-type="${type}">需要一点提示？${e.hints?'（再看一层）':''}</button>${e.hints?`<div class="hint">${hints[Math.min(1,e.hints-1)]}</div>`:''}`;}
function centerTable(points,result,names=[]){return `<div class="table-scroll"><table><thead><tr><th>簇</th><th>中心（睡眠，运动）</th><th>样本数</th><th>特征</th></tr></thead><tbody>${result.centers.map((c,i)=>`<tr><td><i class="dot" style="background:${C[i]}"></i>${esc(names[i]||String.fromCharCode(65+i))}</td><td class="mono">(${c.map(v=>fmt(v,2)).join(', ')})</td><td>${result.labels.filter(x=>x===i).length}</td><td>${KM.feature(c)}</td></tr>`).join('')}</tbody></table></div>`;}
function activeResult(){return S.experiments[S.k]?.result;}
function reasonPending(){return !!S&&reasonRequest?.studentId===studentId&&reasonRequest.key===Tutor.reasonKey(S);}
function reasonFeedbackHtml(){if(reasonPending())return '<div class="soft small">星伴正在结合你的分组记录分析理由…</div>';const review=S.reasonReview;if(!review)return '';if(review.key!==Tutor.reasonKey(S))return '<p class="small muted">理由或实验已修改，保存方案后可获取新的反馈。</p>';return `<div class="soft"><h4>选择 k 的理由反馈</h4><span class="small muted">${esc(review.source)} · 供修改参考，教师复核</span><p style="margin:8px 0 0;white-space:pre-line;overflow-wrap:anywhere">${esc(review.text)}</p><p class="small muted" style="margin:10px 0 0">可根据反馈修改理由，再次保存方案。</p></div>`;}
function refreshReasonFeedback(){const el=$('#reasonFeedback');if(el&&S)el.innerHTML=reasonFeedbackHtml();const button=$('#reasonForm button');if(button&&S)button.disabled=Object.keys(S.experiments).length<2||!activeResult()||reasonPending();}
async function reviewReason(){if(reasonPending())return;const snapshot=KM.clone(S),request={studentId,key:Tutor.reasonKey(snapshot)};reasonRequest=request;refreshReasonFeedback();try{const r=await Store.chat('reason',snapshot,'');if(!S||studentId!==request.studentId||Tutor.reasonKey(S)!==request.key||reasonRequest!==request)return;S.reasonReview={key:request.key,text:r.text.slice(0,300),source:r.source,at:new Date().toISOString()};S.messages.push({role:'assistant',text:S.reasonReview.text,source:r.source});S.messages=S.messages.slice(-30);persist();refreshTutor();}finally{if(reasonRequest===request)reasonRequest=null;if(S&&studentId===request.studentId)refreshReasonFeedback();}}
function viewLab(){const result=activeResult(),keys=Object.keys(S.experiments);return `${S.previousDataset?`<div class="notice">教学样本已更新，请重新比较 k。此前的实验、理由与个人成果已保留。<button class="ghost small" data-action="downloadPrevious">下载此前实验记录 ↓</button></div>`:''}<section class="card"><div class="row between" style="margin-bottom:20px"><h3 style="margin:0">40 个教学样本，你来决定怎么分</h3><span class="tag neutral">模拟数据 · 可重复实验</span></div><div class="lab-layout"><div><div class="plot-wrap">${plot(KM.DATA,result?.centers||[],result?.labels||[])}${legend(S.k)}</div><p class="small muted" style="margin:10px 0 0">样本之间有连续过渡，没有预设类别标签。固定同一批样本比较 k，观察边界附近的点如何变化。</p></div><div class="task"><h3>这次分几类？</h3><div class="row lab-k">${[2,3,4].map(k=>`<button class="${S.k===k?'active':''}" data-action="setK" data-k="${k}">${k}<small>个簇</small></button>`).join('')}</div><button class="primary" data-action="runLab">运行 K-means →</button>${result?`<div class="success small">中心已稳定 · ${result.iterations} 轮迭代</div><button class="small" data-action="rerunLab">换一组随机起点</button>`:''}<div class="soft"><h4>留意三个问题</h4><p>k 是谁定的？<br>换 k，哪些点被合并、拆开或改变归属？<br>分类更细时，哪些差异更清楚，哪些边界仍难解释？</p></div><details><summary>为什么换 k 都能分组？</summary>K-means 会按你指定的 k 分组，能分出来不代表它是唯一正确的类别数。这里固定40个教学样本，每次尝试24组样本起点，保留组内更紧凑的结果；请结合用途、群体差异与边界样本解释选择。</details></div></div></section><section class="card"><div class="row between"><h3>我的分组记录</h3><span class="tag">已比较 ${keys.length} 种 k</span></div>${keys.length?`<div class="experiment-tab">${keys.map(k=>`<button data-action="setK" data-k="${k}" class="${S.k===+k?'active':''}">k=${k} · 已记录</button>`).join('')}</div>${result?centerTable(KM.DATA,result):'<p class="small muted">运行当前 k 后，这里会留下它的记录。</p>'}`:'<p class="muted small">运行一次聚类，中心与成员数就会记录在这里。</p>'}<div class="divider"></div><form id="reasonForm"><label for="reason">我选择 k=${S.k}，因为……</label><textarea id="reason" name="reason" maxlength="400" minlength="12" placeholder="至少比较两种 k。指出哪些群体被合并或拆开，再解释你的选择为何适合呈现作息特点。" required>${esc(S.reason)}</textarea><div class="row between" style="margin-top:14px"><span class="small muted">保存后星伴会分析理由，最终由教师复核；没有唯一正确的 k。</span><button class="primary" ${keys.length<2||!result||reasonPending()?'disabled':''}>保存方案，准备展示 →</button></div></form><div id="reasonFeedback" aria-live="polite" style="margin-top:16px">${reasonFeedbackHtml()}</div></section>`;}
function viewFinish(){const result=activeResult();if(!result)return `<section class="card"><h3>还需要一份分组方案</h3><p>老师开放了这个环节，但还没有你的实验结果。先回到实验台，运行并选择一个 k。</p><button class="primary" data-action="stage" data-stage="2">回到项目实施 →</button></section>`;return `<section class="card"><div class="row between"><h3>我的班级作息画像</h3><span class="tag">k = ${S.k} · 40 个教学样本</span></div><p class="small muted">你的依据：${esc(S.reason||'尚未填写选择理由')}</p><div class="completion-flow"><span>${S.named?'✓':'1'} 给簇起名</span><span>${S.named?'✓':'2'} 看命名反馈</span><span>${S.selftest?'✓':'3'} 输入自己数据</span><span>${S.selftest?'✓':'4'} 对照与反思</span></div>${!S.named?`<form id="namesForm"><div class="grid2">${result.centers.map((c,i)=>`<div class="name-item"><h4><i class="dot" style="background:${C[i]}"></i>簇 ${String.fromCharCode(65+i)} · ${result.labels.filter(x=>x===i).length} 个样本</h4><p>${KM.feature(c)}<br>中心 (${c.map(v=>fmt(v,1)).join(', ')})</p><label>给这一簇起个名字<input name="name${i}" value="${esc(S.names[i]||'')}" maxlength="16" required placeholder="描述作息，不评价人"></label></div>`).join('')}</div><button class="primary" style="margin-top:18px">提交名字，听听反馈 →</button></form>`:`${centerTable(KM.DATA,result,S.names)}<div class="soft" style="margin-top:18px"><span class="small muted">命名反馈 · ${esc(S.nameFeedbackSource||'本地导学')}</span><p style="margin:8px 0 0">${esc(S.nameFeedback||Tutor.fallback('names',S))}</p></div><button class="ghost small" data-action="rename" style="margin-top:10px">调整簇名</button>`}</section>${S.named?`<section class="card"><div class="row between"><h3>这次，把你自己的数据放进来</h3><span class="tag neutral">40 + 1 个样本重新聚类</span></div><p class="small muted">选择同一个时间口径，例如最近一周的每日平均时长。</p><form id="selfForm"><div class="grid2"><div class="field"><label for="sleep">每天睡眠（小时）</label><input id="sleep" name="sleep" type="number" min="0" max="24" step=".1" value="${S.selftest?.sleep??''}" placeholder="例如：8" required></div><div class="field"><label for="move">每天运动（分钟）</label><input id="move" name="move" type="number" min="0" max="1440" step="1" value="${S.selftest?.move??''}" placeholder="例如：30" required></div></div><div class="row between"><span class="small muted">睡眠 6–9 h、运动 0–90 min 映射至 0–10 分。</span><button class="primary">标准化并重新聚类 →</button></div><details style="margin-top:15px"><summary>如果我的时长超出参考范围呢？</summary>仍用同一把尺子线性换算，分数可以小于 0 或大于 10，图表随之扩展。不会悄悄修改你的数据；结果也不是健康诊断。</details></form></section>`:''}${S.selftest?selfResultHtml():''}`;}
function selfResultHtml(){const t=S.selftest,result=t.result,group=t.cluster,same=t.type===S.vote;return `<section class="result-card" id="personalCard">${artMarkup(currentCardArt(t))}<div class="seal">✦</div><div class="eyebrow">MY RHYTHM CARD / 我的作息星人卡</div><span class="small muted">${esc(S.name)} · 本次输入的作息画像</span><h2>${esc(S.names[group])}</h2><p>${KM.feature(result.centers[group])}</p><div class="row"><span class="tag">睡眠 ${t.sleep} h</span><span class="tag">运动 ${t.move} min</span><span class="tag">标准化 (${t.point.map(v=>fmt(v,1)).join(', ')})</span></div><div class="compare"><div><span>我最初的猜测</span><strong>${esc(KM.TYPES[S.vote]||'未投票')}</strong></div><span>→</span><div><span>按本簇特征对照</span><strong>${KM.TYPES[t.type]}</strong></div></div><p class="small">${S.vote===null?'尚无最初猜测。':same?'与最初猜测相近。':'与最初猜测不同。'}名字由你来取，比较依据是中心的特征，不是名字是否相同。</p><p class="small muted">这次有 ${result.labels.slice(0,40).filter(x=>x===group).length} 个教学样本与你同簇。样本数不代表真实同学人数。</p><div class="divider"></div><p><strong>机器分的是作息，不是定义你这个人。</strong></p><div class="row"><button data-action="downloadCard">保存个人卡片 ↓</button><button class="ghost small" data-action="downloadRecord">下载学习记录</button></div></section><section class="card"><h3>看见数据，也解释差异</h3><div class="plot-wrap">${plot([...KM.DATA,t.point],result.centers,result.labels,{self:40})}${legend(S.k)}</div><div class="soft" style="margin-top:17px"><span class="small muted">自测反馈 · ${esc(t.feedbackSource||'本地导学')}</span><p style="margin:7px 0 0">${esc(t.feedback||Tutor.fallback('selftest',S))}</p></div><p class="small muted" style="margin-top:12px">新旧簇按中心最接近的整体对应关系沿用名字；加入自己后中心和成员可能改变。k≠3 时，与导入三种称呼的对照仅作粗略参考。</p></section><section class="card"><h3>最后，用五句话回看自己的学习</h3><form id="ratingsForm"><div class="ratings">${RATINGS.map((r,i)=>`<label class="rating-row">${r}<select name="rating${i}" required><option value="">选择自评</option>${['完全做到','基本做到','还需努力'].map(v=>`<option ${S.selfRatings[i]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}</div><button class="primary" style="margin-top:22px">${S.completed[3]?'更新自评':'完成这次探索'} ✓</button></form>${S.completed[3]?'<div class="success" style="margin-top:18px">已完成。保留好奇心，下一次换一组数据，再看看会发生什么。</div>':''}</section>`;}
async function say(event,question=''){
 if(chatBusy&&event==='chat')return;const sessionId=studentId,nameSnapshot=JSON.stringify(S.names),selfAt=S.selftest?.at,handRound=S.handRound;
 if(question){S.messages.push({role:'user',text:question});if(S.stage===1){const e=S.step<=2?S.evidence.distance:S.evidence.mean;if(!e.passed)e.hints++;persist();}}
 chatBusy=true;refreshTutor();
 try{let r;if((event==='chat'&&S.stage===1&&(!S.evidence.distance.passed||!S.evidence.mean.passed))||event==='hint')r={text:Tutor.fallback('chat',S,question||'怎样计算'),source:'本地导学'};else r=await Store.chat(event,S,question);
  if(!S||studentId!==sessionId||S.handRound!==handRound)return;r.text=r.text.slice(0,300);S.messages.push({role:'assistant',...r});S.messages=S.messages.slice(-30);
  if(event==='names'&&JSON.stringify(S.names)===nameSnapshot){S.nameFeedback=r.text;S.nameFeedbackSource=r.source;}
  if(event==='selftest'&&S.selftest?.at===selfAt){S.selftest.feedback=r.text;S.selftest.feedbackSource=r.source;}persist();
 }finally{chatBusy=false;if(S&&studentId===sessionId){if((event==='names'||event==='selftest')&&!$('input:focus,textarea:focus,select:focus'))render();else refreshTutor();}}
}
function refreshTutor(){const el=$('.tutor');if(el&&S){el.outerHTML=tutorHtml();const box=$('#chatMessages');box.scrollTop=box.scrollHeight;}}
function checkpoint(type,answer,passed){const e=S.evidence[type];if(e.attempts.length>=1000)throw Error('本轮作答已达保存上限，请回到初始化开始新一轮。');e.attempts.push({answer,passed,hints:e.hints,at:new Date().toISOString()});e.passed=passed;}
function resetAfterLab(){S.names=[];S.named=false;S.selftest=null;S.completed[2]=false;S.completed[3]=false;S.reason='';S.selfRatings=[];delete S.reasonReview;}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function cardDownload(name,names,t,k,art=null){let artImage=null;if(art){try{const url=await artData(art);artImage=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=url;});}catch{toast('插画未能载入，将下载文字数据卡片。');}}const cv=document.createElement('canvas');cv.width=1000;cv.height=artImage?1580:1120;const ctx=cv.getContext('2d');ctx.fillStyle='#edf3e7';ctx.fillRect(0,0,1000,cv.height);ctx.strokeStyle='#c7d8bf';ctx.lineWidth=2;ctx.strokeRect(30,30,940,cv.height-60);if(artImage){const scale=Math.max(850/artImage.width,390/artImage.height),w=850/scale,h=390/scale;ctx.drawImage(artImage,(artImage.width-w)/2,(artImage.height-h)/2,w,h,75,60,850,390);ctx.font='18px Microsoft YaHei';ctx.fillStyle='#6c8078';ctx.fillText('AI 生成插画 · 用于装饰',75,480);ctx.translate(0,460);}ctx.fillStyle='#176b61';ctx.font='bold 30px "Microsoft YaHei"';ctx.fillText('✦  作息星球 / K-MEANS LAB',75,110);ctx.fillStyle='#6c8078';ctx.font='23px "Microsoft YaHei"';ctx.fillText('我的作息星人卡 · '+name,75,180);ctx.fillStyle='#176b61';ctx.font='bold 60px "Microsoft YaHei"';const title=names[t.cluster];const lines=title.length>9?[title.slice(0,9),title.slice(9)]:[title];lines.forEach((l,i)=>ctx.fillText(l,75,290+i*73));ctx.font='28px "Microsoft YaHei"';ctx.fillText(KM.feature(t.result.centers[t.cluster]),75,455);ctx.fillStyle='#fffaf0';ctx.fillRect(75,510,850,150);ctx.fillStyle='#365d4c';ctx.font='29px "Microsoft YaHei"';ctx.fillText('每日睡眠  '+t.sleep+' 小时',110,570);ctx.fillText('每日运动  '+t.move+' 分钟',110,620);ctx.font='24px "Microsoft YaHei"';ctx.fillText('k = '+k+' · 40 个教学样本 + 我的数据',75,735);ctx.fillText(t.result.labels.slice(0,40).filter(x=>x===t.cluster).length+' 个教学样本与我同簇',75,785);ctx.font='21px "Microsoft YaHei"';ctx.fillStyle='#6c8078';ctx.fillText('仅反映本次输入；样本数不代表真实同学人数。',75,842);ctx.strokeStyle='#c2d2b9';ctx.beginPath();ctx.moveTo(75,915);ctx.lineTo(925,915);ctx.stroke();ctx.fillStyle='#176b61';ctx.font='bold 28px "Microsoft YaHei"';ctx.fillText('机器分的是作息，不是定义你这个人。',75,985);ctx.font='18px "Microsoft YaHei"';ctx.fillStyle='#6c8078';ctx.fillText(new Date().toLocaleDateString('zh-CN')+'  ·  学习记录',75,1030);cv.toBlob(blob=>{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='我的作息星人卡.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
function bindPlot(){
 const svg=$('#plot');if(!svg)return;
 if(animateCenters&&S?.previous){animateCenters=false;const before=KM.clone(S.previous),after=KM.clone(S.centers),start=performance.now(),reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;
  const frame=now=>{if(!document.contains(svg))return;const t=reduce?1:Math.min(1,(now-start)/650),ease=1-Math.pow(1-t,3);
   before.forEach((p,i)=>{const x=p[0]+(after[i][0]-p[0])*ease,y=p[1]+(after[i][1]-p[1])*ease;svg.querySelector(`[data-center="${i}"]`).setAttribute('transform',`translate(${62+x*34} ${378-y*34})`);});if(t<1)requestAnimationFrame(frame);};requestAnimationFrame(frame);
 }
}
document.addEventListener('input',e=>{if(!S)return;if(e.target.id==='reason'){S.reason=e.target.value;refreshReasonFeedback();clearTimeout(saveTimer);saveTimer=setTimeout(persist,400);}if(e.target.closest('#distanceForm,#meanForm')){S.handDrafts??={};S.handDrafts[e.target.name]=e.target.value;clearTimeout(saveTimer);saveTimer=setTimeout(persist,400);}});
document.addEventListener('change',e=>{if(!S||e.target.dataset.centerSample===undefined)return;const centers=KM.clone(KM.handView(S,1).centers);centers[+e.target.dataset.centerSample]=KM.HAND[+e.target.value].slice();if(!KM.sampleCenters(centers)){toast('请选择三个不同的样本点。');render();return;}S.centerDraft=centers;persist();render();});

document.addEventListener('keydown',e=>{const p=e.target.closest('[data-point]');if(p&&(e.key==='Enter'||e.key===' ')){e.preventDefault();if(S){S.selected=+p.dataset.point;render();}}});
document.addEventListener('click',async e=>{const point=e.target.closest('[data-point]');if(point&&S){S.selected=+point.dataset.point;render();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;feedback='';try{
  if(a==='tryLocal'){
    const name=$('#studentName')?.value||'',className=$('#className')?.value||'';
    const url=new URL(location.href);url.searchParams.set('mode','experience');url.searchParams.delete('class');history.replaceState(null,'',url);params.set('mode','experience');params.delete('class');
    const current=await Store.init();S=current?.state||null;studentId=current?.id||null;room=current?.room||{};votePick=S?.vote??null;render();
    if(!S){$('#studentName').value=name;$('#className').value=className;(name?$('#className'):$('#studentName')).focus();}return;
  }
  if(a==='logout'){Store.logout();S=null;studentId=null;votePick=null;render();return;}
  if(a==='stage'){const next=+b.dataset.stage;if(next<=allowed()){S.stage=next;persist();render();window.scrollTo({top:0,behavior:'smooth'});}return;}
  if(a==='votePick'){votePick=+b.dataset.value;render();return;}
  if(a==='vote'){S.vote=votePick??S.vote;S.completed[0]=true;persist();render();refreshVotes();say('vote');return;}
  if(a==='normalize'){S.normalized=true;S.exploreView=0;persist();render();say('normalize');return;}
  if(a==='resetCenters'){S.centerDraft=KM.clone(KM.INITIAL);persist();render();return;}
  if(a==='exploreView'||a==='exploreBack'||a==='resumeExplore'){const target=a==='exploreView'?+b.dataset.step:a==='resumeExplore'?S.step:exploreStep()-1;if(target>=-1&&target<=S.step){S.exploreView=target;animateCenters=false;persist();render();}return;}
  if(a==='exploreNext'){const step=exploreStep();if(step===1){const changed=KM.startHand(S,KM.handView(S,1).centers);if(changed){S.handDrafts={};if(S.handHistory.length)toast('已开始新一轮练习，此前作答已保留。');}persist();render();say('init');return;}if(step<S.step){S.exploreView=step+1;persist();render();return;}if((step===2&&(!S.evidence.distance.passed||S.labels.some(x=>x<0)))||(step===3&&!S.updated)||(step===4&&!S.converged))return;S.step=Math.min(5,step+1);S.exploreView=S.step;persist();render();say(['','k','init','assign','mean','converge'][S.step]);return;}

  if(a==='hint'){const type=b.dataset.type;S.evidence[type].hints++;persist();render();return;}
  if(a==='point'){S.selected=+b.dataset.index;render();return;}
  if(a==='assignOne'){if(exploreStep()!==S.step||S.step!==2)return;if(!S.evidence.distance.passed)return;S.labels[S.selected]=KM.nearest(KM.HAND[S.selected],S.centers);const n=S.labels.findIndex(x=>x<0);if(n>=0)S.selected=n;persist();render();say('assign');return;}
  if(a==='assignAll'){if(exploreStep()!==S.step||S.step!==2)return;if(!S.evidence.distance.passed)return;S.labels=KM.assign(KM.HAND,S.centers);persist();render();say('assign');return;}
  if(a==='updateCenters'){if(exploreStep()!==S.step||S.step!==3||S.updated)return;if(!S.evidence.mean.passed)return;S.previous=KM.clone(S.centers);S.centers=KM.update(KM.HAND,S.labels,S.centers);S.updated=true;animateCenters=true;persist();render();say('mean');return;}
  if(a==='repeat'){if(exploreStep()!==S.step||S.step!==4)return;S.previous=KM.clone(S.centers);S.labels=KM.assign(KM.HAND,S.centers);S.centers=KM.update(KM.HAND,S.labels,S.centers);S.converged=KM.movement(S.previous,S.centers)<1e-8;S.repeatCount++;animateCenters=true;persist();render();say('repeat');return;}
  if(a==='completeExplore'){if(!S.converged||!S.evidence.distance.passed||!S.evidence.mean.passed)return;S.completed[1]=true;persist();render();toast('探究完成，实验台已解锁。');return;}
  if(a==='setK'){if(S.k!==+b.dataset.k){S.k=+b.dataset.k;resetAfterLab();persist();}render();return;}
  if(a==='runLab'||a==='rerunLab'){const seed=a==='rerunLab'?++S.seed:100,result=KM.canonical(KM.run(KM.DATA,S.k,{seed}));resetAfterLab();S.experiments[S.k]={result,at:new Date().toISOString(),seed};persist();render();say('lab');return;}
  if(a==='rename'){S.named=false;S.selftest=null;S.completed[3]=false;persist();render();return;}
  if(a==='downloadCard'){await cardDownload(S.name,S.names,S.selftest,S.k,currentCardArt(S.selftest));return;}
  if(a==='downloadPrevious'){download('作息星球-此前实验记录.json',JSON.stringify({...S.previousDataset,points:KM.dataset(S.previousDataset.datasetVersion)},null,2),'application/json');return;}
  if(a==='downloadRecord'){download('作息星球-学习记录.json',JSON.stringify(S,null,2),'application/json');return;}
  if(a==='quick'){await say('chat',b.dataset.question);return;}
  if(a==='downloadStudentPrevious'){const previous=roomStudents()[+b.dataset.index]?.state.previousDataset;if(previous)download('作息星球-此前实验记录.json',JSON.stringify({...previous,points:KM.dataset(previous.datasetVersion)},null,2),'application/json');return;}
  if(a==='teacherRefresh'){await loadTeacher();return;}
  if(a==='chooseRoom'){selectTeacherRoom(b.dataset.code);renderTeacher();return;}
  if(a==='focusCreate'){projector=false;renderTeacher();$('#roomForm input').focus();$('#roomForm').scrollIntoView({block:'center',behavior:'smooth'});return;}
  if(a==='copyClassCode'||a==='copyStudentLink'){const selected=teacherData?.rooms.find(r=>r.code===roomCode);if(selected&&Store.mode==='cloud')await copyClassroomValue(a==='copyClassCode'?selected.code:studentEntry(selected));return;}
  if(a==='projector'){projector=!projector;renderTeacher();return;}
  if(a==='unlock'){await Store.room('unlock',{code:roomCode,stage:3});await loadTeacher();toast('已开放全部环节；未完成的学习证据仍保留原状态。');return;}
  if(a==='freeze'){const record=teacherData.students.find(x=>x.id===$('#freezeStudent').value);if(!record)throw Error('请先选择一位已有命名成果的学生方案。');const s=record.state,result=s.experiments[s.k].result;await Store.room('freeze',{code:roomCode,snapshot:{datasetVersion:s.datasetVersion||KM.LEGACY_DATA_VERSION,k:s.k,centers:result.centers,labels:result.labels,names:s.names,reason:s.reason,participantCount:roomStudents().length}});await loadTeacher();toast('成果已定格，课后图鉴可以访问。');return;}
  if(a==='unfreeze'){await Store.room('unfreeze',{code:roomCode});await loadTeacher();return;}
  if(a==='postDownload'){await cardDownload('课后访客',postData.snapshot.names,postResult,postData.snapshot.k,currentCardArt(postResult,true));return;}
}catch(err){toast(err.message);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,fd=new FormData(form),button=form.querySelector('button[type="submit"],button:not([type="button"])');if(button)button.disabled=true;feedback='';try{
  if(form.id==='joinForm'){const name=String(fd.get('name')).trim(),className=String(fd.get('className')).trim();if(!name||!className)throw Error('请填写姓名和班级。');const r=await Store.join(name,className,String(fd.get('code')||'').trim());S=r.state;studentId=r.id;room=r.room;votePick=S.vote;render();return;}
  if(form.id==='distanceForm'){if(exploreStep()!==2||S.step!==2)return;const answer={value:fd.get('distance'),cluster:fd.get('cluster')},pass=KM.checkDistance({centers:KM.handInitial(S)},answer.value,answer.cluster);checkpoint('distance',answer,pass);feedback=pass?'判断正确。现在逐个点检验最近归属。':'再检查一下：横纵差值是否分别平方？最近的一簇要比较三个平方和。';persist();render();if(pass)say('distance');return;}
  if(form.id==='meanForm'){if(exploreStep()!==3||S.step!==3||S.updated)return;const answer={x:fd.get('x'),y:fd.get('y')},pass=KM.checkMean({centers:KM.handInitial(S)},answer.x,answer.y);checkpoint('mean',answer,pass);feedback=pass?'均值计算正确。现在可以让全部中心移动。':'还需要订正。请数清 B 簇成员，把横、纵坐标分别相加后除以成员数。';persist();render();return;}
  if(form.id==='reasonForm'){S.reason=String(fd.get('reason')).trim();if(!KM.validateReason(S))throw Error('请至少比较两种 k，并用 12–400 字写下选择的依据。');S.completed[2]=true;persist();render();reviewReason();return;}
  if(form.id==='namesForm'){const n=activeResult().centers.length,names=Array.from({length:n},(_,i)=>String(fd.get('name'+i)).trim());if(names.some(x=>!x||x.length>16))throw Error('每个簇都需要一个 1–16 字的名字。');if(new Set(names).size!==n)throw Error('给不同的簇取不同的名字，方便比较。');if(names.some(x=>/废物|垃圾|低能|智障|劣等|懒鬼|笨蛋/.test(x)))throw Error('请描述睡眠和运动特点，避免用贬低人的称呼。');S.names=names;S.named=true;persist();render();await say('names');return;}
  if(form.id==='selfForm'){const sleep=KM.number(fd.get('sleep')),move=KM.number(fd.get('move')),point=KM.normalize(sleep,move),baseResult=activeResult(),result=KM.align(KM.run([...KM.DATA,point],S.k,{seed:2026}),baseResult.centers),cluster=result.labels[40];S.selftest={sleep,move,point,result,cluster,type:KM.typed(result.centers[cluster]),at:new Date().toISOString()};S.completed[3]=false;persist();render();await say('selftest');return;}
  if(form.id==='ratingsForm'){S.selfRatings=RATINGS.map((_,i)=>String(fd.get('rating'+i)));S.completed[3]=true;persist();render();say('finish');return;}
  if(form.id==='chatForm'){const q=$('#chatInput').value.trim();if(q)await say('chat',q);return;}
  if(form.id==='teacherLogin'){await Store.login(String(fd.get('key')));await loadTeacher();return;}
  if(form.id==='roomForm'){const r=await Store.room('create',{name:String(fd.get('name')).trim()});selectTeacherRoom(r.code||r.name);await loadTeacher();window.scrollTo({top:0,behavior:'smooth'});toast(Store.mode==='cloud'?'课堂已创建，课堂码已显示在页面顶部。':'已创建本机体验班级；正式课堂码请在正式教师端生成。');return;}
  if(form.id==='atlasForm'){const code=String(fd.get('code')).trim();postData=await Store.atlas(code);if(!postData)throw Error('这个课堂还没有定格成果，请向老师确认课堂码。');params.set('class',code);renderAfter();return;}
  if(form.id==='postForm'){const sleep=KM.number(fd.get('sleep')),move=KM.number(fd.get('move')),point=KM.normalize(sleep,move),snap=postData.snapshot,result=KM.align(KM.run([...KM.dataset(snap.datasetVersion),point],snap.k,{seed:2026}),snap.centers),cluster=result.labels[40];postResult={sleep,move,point,result,cluster};renderAfter();return;}
}catch(err){if(form.id==='joinForm'&&$('#joinError')){const error=$('#joinError');error.textContent=err.message+(Store.mode==='cloud'?' 如需试用，请点击上方“无需课堂码，先体验”。':'');error.hidden=false;}else toast(err.message);}finally{if(button&&document.contains(button))button.disabled=false;}});
async function refreshVotes(){if(!S||S.stage!==0||!S.completed[0])return;try{const r=await Store.refresh();room=r?.room||room;const votes=room.votes||[0,0,0];if(Store.mode==='local'){const all=await Store.teacher();votes.fill(0);all.students.filter(x=>x.state.className===S.className).forEach(x=>{if(x.state.vote!==null)votes[x.state.vote]++;});}if($('#voteBars'))$('#voteBars').innerHTML=bars(KM.TYPES,votes);}catch{}}
function bars(labels,counts,colors=C){const total=counts.reduce((s,n)=>s+n,0);return `<div class="bars">${labels.map((t,i)=>`<div><div class="bar-label"><span>${esc(t)}</span><span>${counts[i]} 人 · ${total?Math.round(counts[i]/total*100):0}%</span></div><div class="bar-track"><div class="bar-fill" style="width:${total?counts[i]/total*100:0}%;background:${colors[i%colors.length]}"></div></div></div>`).join('')}</div>`;}
function roomStudents(){const r=teacherData?.rooms.find(r=>r.code===roomCode);return (teacherData?.students||[]).filter(x=>Store.mode==='cloud'?x.code===roomCode:x.state.className===r?.name);}
function selectTeacherRoom(code){roomCode=code;sessionStorage.setItem('sleep-selected-room-'+Store.mode,code);}
async function loadTeacher(){try{teacherData=await Store.teacher();const saved=roomCode||sessionStorage.getItem('sleep-selected-room-'+Store.mode);selectTeacherRoom(teacherData.rooms.some(r=>r.code===saved)?saved:teacherData.rooms[0]?.code||'');renderTeacher();}catch(e){teacherData=null;renderTeacher(e.message);}}
function studentEntry(r){const url=new URL(entryHref(),location.href);url.searchParams.set('class',r.code);url.searchParams.set('className',r.name);return url.href;}
function teacherJoinCard(r){
 if(Store.mode!=='cloud')return `<section class="card classroom-access local-classroom" aria-labelledby="classroomAccessTitle"><div><span class="tag neutral">当前为本机体验</span><h3 id="classroomAccessTitle">尚未生成正式课堂码</h3><p>这里的班级记录只在当前浏览器保存，不能用来让其他设备加入。请进入正式教师端，创建课堂后获取课堂码。</p>${location.protocol==='file:'?'<p class="small muted">先运行“启动预览.cmd”，再打开 http://localhost:4186/?view=teacher。</p>':'<a class="primary access-link" href="index.html?view=teacher">进入正式教师端，生成课堂码 →</a>'}</div></section>`;
 if(!r)return `<section class="card classroom-access" aria-labelledby="classroomAccessTitle"><div><span class="tag">准备开课</span><h3 id="classroomAccessTitle">创建课堂后，这里会显示课堂码</h3><p>填写班级名称，点击“创建课堂”。系统会生成供学生加入的课堂码和入口链接。</p><button class="primary" data-action="focusCreate">去创建课堂 →</button></div></section>`;
 const link=studentEntry(r);return `<section class="card classroom-access" aria-labelledby="classroomAccessTitle"><div class="classroom-code-block"><span class="tag">${esc(r.name)}</span><h3 id="classroomAccessTitle">学生课堂码</h3><output id="teacherClassCode" class="classroom-code" aria-label="当前课堂码">${esc(r.code)}</output><p class="small muted">${r.frozen?'成果已定格；恢复课堂后可继续加入。':'学生填写此码加入当前课堂。'}</p></div><div class="classroom-invite"><div class="row"><button class="primary" data-action="copyClassCode">复制课堂码</button><button data-action="copyStudentLink">复制学生链接</button><a href="${esc(link)}" target="_blank" rel="noopener">打开学生入口 ↗</a></div><label for="studentEntryLink" style="margin-top:15px">学生入口链接<input id="studentEntryLink" value="${esc(link)}" readonly></label><p class="small muted">链接已带上班级和课堂码，学生填写姓名即可加入。</p>${/^(localhost|127\.0\.0\.1|\[::1\])$/.test(location.hostname)?'<p class="small muted">当前是本机地址；跨设备上课请使用部署网址或教师电脑的局域网地址打开本站，再复制链接。</p>':''}</div></section>`;
}
async function copyClassroomValue(text){try{await navigator.clipboard.writeText(text);}catch{const input=document.createElement('textarea');input.value=text;input.style.cssText='position:fixed;left:-10000px;top:0';document.body.append(input);input.select();const copied=document.execCommand('copy');input.remove();if(!copied){toast('自动复制未成功，请选中页面中的课堂码或学生链接复制。');return;}}toast('已复制。');}
function renderTeacher(error=''){if(!teacherData){$('#app').innerHTML=header()+`<main class="login-teacher card"><div class="eyebrow">TEACHER WORKSPACE</div><h2>把全班的探索看在一起</h2><p class="small muted">教师入口用于创建课堂、查看进度与学习证据。</p>${Store.mode==='cloud'&&!Store.localTeacher?`<form id="teacherLogin"><div class="field"><label for="teacherKey">教师口令</label><input id="teacherKey" name="key" type="password" autocomplete="current-password" required placeholder="输入部署时设置的教师口令"></div><button class="primary wide">进入教师工作台 →</button></form>${error?`<p class="error" style="margin-top:15px">${esc(error)}</p>`:''}`:`<button class="primary" data-action="teacherRefresh">${Store.mode==='cloud'?'重新连接教师工作台 →':'打开本机体验记录 →'}</button>${error?`<p class="error" style="margin-top:15px">${esc(error)}</p>`:''}`}</main>`;return;}const students=roomStudents(),r=teacherData.rooms.find(x=>x.code===roomCode),votes=[0,0,0],ks=[0,0,0],self=[0,0,0];students.forEach(({state:s})=>{if(s.vote!==null)votes[s.vote]++;if(s.completed[2])ks[s.k-2]++;if(s.selftest)self[s.selftest.type]++;});const done=students.filter(x=>x.state.completed[3]).length,ready=students.filter(x=>x.state.named&&x.state.experiments[x.state.k]);$('#app').innerHTML=header()+`<main class="teacher ${projector?'projector':''}"><div class="row between" style="margin-bottom:25px"><div><div class="eyebrow">TEACHER WORKSPACE</div><h2>每一步探索，都有迹可循</h2></div><div class="row"><button data-action="teacherRefresh">刷新记录</button><button data-action="projector">${projector?'退出投屏':'投屏大字模式'}</button></div></div>${teacherJoinCard(r)}${teacherFeatures()}<div class="teacher-shell"><aside class="teacher-nav card"><h3>我的课堂</h3>${teacherData.rooms.map(x=>`<button class="room-button ${x.code===roomCode?'active':''}" data-action="chooseRoom" data-code="${esc(x.code)}">${esc(x.name)}</button>`).join('')}<div class="divider"></div><form id="roomForm"><label>创建班级<input name="name" placeholder="例如：高一（3）班" maxlength="40" required></label><button class="wide" style="margin-top:10px">创建课堂 ＋</button></form>${r?`<div class="divider"></div><button class="wide danger small" data-action="deleteRoom" data-code="${esc(r.code)}">删除当前班级</button><p class="small muted">${Store.mode==='cloud'?'课堂码和学生入口显示在页面顶部。':'本机体验班级：'+esc(r.name)}</p>${Store.mode==='local'?`<a class="small" href="${esc(studentEntry(r))}" target="_blank" rel="noopener">打开学生入口 ↗</a>`:''}<button class="wide" data-action="unlock" style="margin-top:20px">开放全部环节</button><p class="small muted" style="margin-top:8px">开放环节不会补造完成记录。</p>`:''}</aside><div class="dashboard">${r?`<div class="stats"><div class="metric"><b>${students.length}</b><span>真实参与学生</span></div><div class="metric"><b>${done}</b><span>完成全部任务</span></div><div class="metric"><b>${students.filter(x=>x.state.evidence.distance.passed&&x.state.evidence.mean.passed).length}</b><span>通过两项计算</span></div><div class="metric"><b>40</b><span>预置教学样本</span></div></div><div class="grid2"><section class="card"><h3>01 / 最初的直觉</h3>${bars(KM.TYPES,votes)}</section><section class="card"><h3>02 / 同学选择的 k</h3>${bars(['k = 2','k = 3','k = 4'],ks)}<p class="small muted" style="margin:15px 0 0">选择人数不是正确性投票。</p></section><section class="card"><h3>03 / 自测特征对照</h3>${bars(KM.TYPES,self)}<p class="small muted" style="margin:15px 0 0">按各自结果中心粗略对照导入三类；各人 k 与命名可能不同。</p></section><section class="card"><h3>04 / 我们的起名墙</h3><div class="name-wall">${ready.length?ready.flatMap(({state:s})=>s.names.map(n=>`<span class="name-note">${esc(n)} <small>· k=${s.k}</small></span>`)).join(''):'<p class="small muted">等待同学们为群体赋予名字。</p>'}</div></section></div><section class="card private"><h3>学习证据与需要帮助的同学</h3><div class="table-scroll"><table><thead><tr><th>学生</th><th>进度</th><th>距离判断</th><th>均值计算</th><th>k 的选择依据（教师复核）</th></tr></thead><tbody>${students.map(({state:s})=>`<tr><td>${esc(s.name)}</td><td>${s.completed.filter(Boolean).length}/4</td><td>${KM.grade(s.evidence.distance)}<br><small>${s.evidence.distance.attempts.length} 次尝试</small></td><td>${KM.grade(s.evidence.mean)}<br><small>${s.evidence.mean.attempts.length} 次尝试</small></td><td class="wrap">${s.reason?`k=${s.k}：${esc(s.reason)}`:'等待提交'}</td></tr>`).join('')||'<tr><td colspan="5">还没有学生加入。</td></tr>'}</tbody></table></div><details style="margin-top:16px"><summary>查看作答过程与学习自评</summary>${students.map(({state:s})=>`<div class="soft" style="margin-bottom:12px"><h4>${esc(s.name)}</h4>${s.previousDataset?`<details><summary>此前样本的实验记录（已归档）</summary><p>k=${s.previousDataset.k}：${esc(s.previousDataset.reason||'尚未填写理由')}</p><p>簇名：${(s.previousDataset.names||[]).map(esc).join('、')||'尚未命名'}</p><button class="small" data-action="downloadStudentPrevious" data-index="${students.findIndex(x=>x.state===s)}">下载此前实验记录 ↓</button></details>`:''}${(s.handHistory||[]).length?`<details><summary>此前手算记录（${s.handHistory.length} 轮）</summary>${s.handHistory.map(handHistoryHtml).join('')}</details>`:''}<p>当前第 ${(s.handRound||0)+1} 轮 · 距离作答：${s.evidence.distance.attempts.map(a=>`${esc(a.answer.value)} / ${String.fromCharCode(65+Number(a.answer.cluster))}（${a.passed?'正确':'需订正'}）`).join('；')||'暂无记录'}</p><p>均值作答：${s.evidence.mean.attempts.map(a=>`(${esc(a.answer.x)}, ${esc(a.answer.y)})（${a.passed?'正确':'需订正'}）`).join('；')||'暂无记录'}</p><p>自评：${s.selfRatings.map((v,i)=>esc(RATINGS[i])+'：'+esc(v)).join('；')||'尚未自评'}</p></div>`).join('')}</details></section><section class="card"><div class="row between"><h3>把课堂成果留到课后</h3><span class="tag">${r.frozen?'成果已定格':'等待定格'}</span></div>${r.frozen?`<p class="small muted">已保存一份共同展示方案。后续修改不会改变这份快照。</p><div class="row"><a href="${viewHref('after',r.code)}" target="_blank" rel="noopener">打开班级作息图鉴 ↗</a><button class="small private" data-action="unfreeze">恢复课堂模式</button></div>`:`<p class="small muted">选取一份已命名方案作为班级展示成果，保留 40 个教学样本及其名字。</p><label class="private">选择展示方案<select id="freezeStudent">${ready.map(x=>`<option value="${esc(x.id)}">${esc(x.state.name)} · k=${x.state.k}</option>`).join('')||'<option value="">尚无可选成果</option>'}</select></label><button class="primary private" data-action="freeze" ${ready.length?'':'disabled'}>定格成果，开启课后图鉴 →</button>`}</section>`:'<section class="card empty">先创建一个班级，就能邀请学生一起探索。</section>'}</div></div></main>`;}
function renderAfter(){if(!postData){$('#app').innerHTML=header()+`<main class="login-teacher card"><div class="eyebrow">AFTER CLASS / 课后探索</div><h2>班级作息图鉴</h2><p class="small muted">输入老师提供的课堂码，回看已经定格的班级成果。</p><form id="atlasForm"><label>课堂码<input name="code" value="${esc(params.get('class')||'')}" required></label><button class="primary wide" style="margin-top:16px">打开图鉴 →</button></form></main>`;return;}const snap=postData.snapshot;$('#app').innerHTML=header()+`<main class="post-class stack"><div class="section-head"><div class="eyebrow">AFTER CLASS / 留下我们的发现</div><h2>${esc(postData.name)} · 作息图鉴</h2><p>课堂成果快照 · ${snap.participantCount} 位实际参与者 · 图中为 40 个教学样本</p></div>${artMarkup(postData.artwork?.cover,'cover')}<section class="card"><div class="grid2"><div class="plot-wrap">${plot(KM.dataset(snap.datasetVersion),snap.centers,snap.labels)}${legend(snap.k)}</div><div><span class="tag">k = ${snap.k}</span><h3 style="margin-top:18px">我们怎样理解这些群体</h3><p class="small muted">${esc(snap.reason)}</p>${centerTable(KM.dataset(snap.datasetVersion),snap,snap.names)}</div></div></section><section class="card"><h3>生成我的作息星人卡</h3><p class="small muted">输入只在当前页面计算，不上传个人时长；与教学样本一起重新聚类。范围外仍按原尺子换算。</p><form id="postForm"><div class="grid2"><label>每日睡眠 / 小时<input name="sleep" type="number" min="0" max="24" step=".1" required></label><label>每日运动 / 分钟<input name="move" type="number" min="0" max="1440" step="1" required></label></div><button class="primary" style="margin-top:15px">看看我的作息星人 →</button></form></section>${postResult?`<section class="result-card">${artMarkup(currentCardArt(postResult,true))}<div class="seal">✦</div><div class="eyebrow">MY RHYTHM CARD</div><h2>${esc(snap.names[postResult.cluster])}</h2><p>${KM.feature(postResult.result.centers[postResult.cluster])}</p><p>睡眠 ${postResult.sleep} h · 运动 ${postResult.move} min</p><p class="small muted">${postResult.result.labels.slice(0,40).filter(x=>x===postResult.cluster).length} 个教学样本与你同簇，不代表真实同学人数。</p><div class="divider"></div><p><strong>机器分的是作息，不是定义你这个人。</strong></p><button data-action="postDownload">保存个人卡片 ↓</button></section>`:''}</main>`;}
async function boot(){try{const current=await Store.init();if(current){S=current.state;studentId=current.id;room=current.room||{};votePick=S.vote;}if(teacherView){S=null;await loadTeacher();}else if(afterView){S=null;if(params.get('class'))postData=await Store.atlas(params.get('class'));renderAfter();}else{render();refreshVotes();}}catch(e){$('#app').innerHTML=header()+`<main class="login-teacher card"><h2>暂时没能加载课堂</h2><p>${esc(e.message)}</p><a href="${entryHref()}">返回入口</a></main>`;}setInterval(async()=>{try{if(teacherView&&teacherData&&!$('input:focus,textarea:focus,select:focus')&&!$('details[open]')&&!$('#featureDialog[open]')){teacherData=await Store.teacher();renderTeacher();}else if(S){const r=await Store.refresh();if(r){const changed=room.frozen!==r.room.frozen||(room.unlocked||0)!==(r.room.unlocked||0)||JSON.stringify(room.artwork)!==JSON.stringify(r.room.artwork);room=r.room;if(changed&&!$('input:focus,textarea:focus,select:focus'))render();refreshVotes();}if($('#modeLabel'))$('#modeLabel').textContent=modeLabel();}}catch{}},window.LEARNING_CONFIG?.pollMs||5000);}
boot();

